// This session's numbers for the Usage and Agents rooms: what the engine
// measures (context, rate limits, cost), what each turn used (tokens, cache),
// how long each tool call took, and which subagents ran. Plain logic: the
// hooks module feeds it from session.measure, turn.complete, tool.call and
// agent.spawn.

import { findSecret } from "./share.mjs";

const COST_SAMPLES = 240;      // about two hours at one sample per 30 s
const SAMPLE_EVERY_MS = 30_000;
const DURATIONS = 200;         // per tool, for the percentiles
const FEED = 40;               // newest tool calls kept for the live feed
const BURN_WINDOW_MS = 15 * 60_000;

export function createUsage() {
  return {
    measured: false,
    context: null,             // { tokens, window, percent }
    breakdown: null,           // the /context breakdown, fetched when asked for
    showBreakdown: false,
    rateLimits: [],            // [{ kind, percentUsed, resetsAt }]
    hasLimits: false,          // ever reported a window (a subscription, not an API key)
    ctxHistory: [],            // context tokens after each main-loop turn, oldest first (the band's chart)
    cost: null,                // { usd }
    startedAt: null,
    model: null,
    costSamples: [],           // [{ at, usd }]
    tokens: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
    tools: new Map(),          // tool name → { count, errors, durations }
    calls: new Map(),          // call key → feed entry, while it runs
    feed: [],                  // [{ key, tool, agentId, summary, at, ms, isError, done }], oldest first
    agents: new Map(),         // agent id → { id, type, description, status, parentId, startedAt, endedAt, tools }
    activity: { state: "idle", tool: null, since: 0 },   // idle | thinking | tool
  };
}

// ---------------------------------------------------------------- engine figures

// A session.measure event or a $.session.usage() answer.
export function applyMeasure(u, m, now) {
  if (!m) return false;
  u.measured = true;
  if (m.context) u.context = { tokens: m.context.tokens, window: m.context.window, percent: m.context.percent };
  if (Array.isArray(m.rateLimits)) {
    u.rateLimits = m.rateLimits;
    if (m.rateLimits.length) u.hasLimits = true;   // a subscription: its windows always show
  }
  if (typeof m.startedAt === "number") u.startedAt = m.startedAt;
  if (m.cost && typeof m.cost.usd === "number") {
    u.cost = { usd: m.cost.usd };
    const last = u.costSamples.at(-1);
    if (!last || last.usd !== m.cost.usd || now - last.at >= SAMPLE_EVERY_MS) {
      u.costSamples.push({ at: now, usd: m.cost.usd });
      if (u.costSamples.length > COST_SAMPLES) u.costSamples.splice(0, u.costSamples.length - COST_SAMPLES);
    }
  }
  return true;
}

// The context's fill after a main-loop turn, for the band's chart.
const CTX_HISTORY = 12;
export function recordTurnContext(u) {
  const t = u.context?.tokens;
  if (t == null) return false;
  u.ctxHistory.push(t);
  if (u.ctxHistory.length > CTX_HISTORY) u.ctxHistory.splice(0, u.ctxHistory.length - CTX_HISTORY);
  return true;
}

// What one turn used (turn.complete's `usage`), the main loop's or a subagent's.
export function applyTurnUsage(u, usage) {
  if (!usage) return false;
  u.tokens.input += usage.input_tokens ?? 0;
  u.tokens.output += usage.output_tokens ?? 0;
  u.tokens.cacheRead += usage.cache_read_input_tokens ?? 0;
  u.tokens.cacheWrite += usage.cache_creation_input_tokens ?? 0;
  if (usage.model) u.model = usage.model;
  return true;
}

export function totalTokens(u) {
  const t = u.tokens;
  return t.input + t.output + t.cacheRead + t.cacheWrite;
}

// The windows to show, 5-hour and 7-day first and always (a window that just
// reset has no reading until the next reply: its percent is null), then any
// others the account has. None at all for an account without windows.
const MAIN_WINDOWS = ["five_hour", "seven_day"];
export function limitWindows(u) {
  if (!u.hasLimits && !u.rateLimits.length) return [];
  const main = MAIN_WINDOWS.map((kind) => u.rateLimits.find((l) => l.kind === kind) ?? { kind, percentUsed: null });
  return [...main, ...u.rateLimits.filter((l) => !MAIN_WINDOWS.includes(l.kind))];
}

// The share of input read from the prompt cache, 0-100, or null before any.
export function cacheRatio(u) {
  const t = u.tokens;
  const input = t.input + t.cacheRead + t.cacheWrite;
  return input ? (t.cacheRead / input) * 100 : null;
}

// Dollars per hour over the last quarter hour, or null with too little to go on.
export function burnRate(u, now) {
  const recent = u.costSamples.filter((s) => now - s.at <= BURN_WINDOW_MS);
  if (recent.length < 2) return null;
  const first = recent[0];
  const last = recent.at(-1);
  const hours = (last.at - first.at) / 3_600_000;
  if (hours < 5 / 60) return null;   // a few minutes say little about an hour
  return (last.usd - first.usd) / hours;
}

// Spend per bucket over the last `n` buckets, oldest first: the sparkline.
export function spendSeries(u, now, n = 12, bucketMs = 5 * 60_000) {
  const out = new Array(n).fill(0);
  const s = u.costSamples;
  for (let i = 1; i < s.length; i++) {
    const back = Math.floor((now - s[i].at) / bucketMs);
    if (back < 0 || back >= n) continue;
    out[n - 1 - back] += Math.max(0, s[i].usd - s[i - 1].usd);
  }
  return out;
}

// ---------------------------------------------------------------- tool calls

// A few words on what a call is about, with anything that looks like a
// secret masked: the command for Bash, a file's name, a search pattern.
export function toolSummary(tool, input = {}) {
  const base = (p) => String(p ?? "").split("/").filter(Boolean).at(-1) ?? "";
  let s;
  switch (tool) {
    case "Bash": s = input.command; break;
    case "Read": case "Write": case "Edit": case "NotebookEdit": s = base(input.file_path ?? input.notebook_path); break;
    case "Grep": s = input.pattern ? `"${input.pattern}"` : ""; break;
    case "Glob": s = input.pattern; break;
    case "WebFetch": s = input.url; break;
    case "WebSearch": s = input.query; break;
    case "Agent": case "Task": s = input.description; break;
    default: s = input.description ?? input.command ?? input.query ?? "";
  }
  s = String(s ?? "").replace(/\s+/g, " ").trim();
  if (findSecret(s)) return "(hidden: looks secret)";
  return s.slice(0, 80);
}

let seq = 0;

export function toolStarted(u, { tool, agentId, input, at }) {
  const key = `c${++seq}`;
  const entry = { key, tool, agentId: agentId ?? null, summary: toolSummary(tool, input), at, ms: null, isError: false, done: false };
  u.calls.set(key, entry);
  u.feed.push(entry);
  if (u.feed.length > FEED) u.feed.splice(0, u.feed.length - FEED);
  if (agentId) {
    // Only agents the session spawned or lists: the engine's own loops
    // (compaction, memory) carry ids nothing else names.
    const a = u.agents.get(agentId);
    if (a) a.tools.set(tool, (a.tools.get(tool) ?? 0) + 1);
  } else {
    u.activity = { state: "tool", tool, since: at };
  }
  return key;
}

export function toolEnded(u, key, { at, isError = false }) {
  const entry = u.calls.get(key);
  if (!entry) return false;
  u.calls.delete(key);
  entry.ms = Math.max(0, at - entry.at);
  entry.isError = isError;
  entry.done = true;
  const t = u.tools.get(entry.tool) ?? { count: 0, errors: 0, durations: [] };
  t.count++;
  if (isError) t.errors++;
  t.durations.push(entry.ms);
  if (t.durations.length > DURATIONS) t.durations.shift();
  u.tools.set(entry.tool, t);
  if (!entry.agentId && u.activity.state === "tool") u.activity = { state: "thinking", tool: null, since: at };
  return true;
}

export function percentile(values, p) {
  if (!values.length) return null;
  const sorted = [...values].sort((a, b) => a - b);
  const i = Math.min(sorted.length - 1, Math.max(0, Math.ceil((p / 100) * sorted.length) - 1));
  return sorted[i];
}

// One row per tool, the most time spent first.
export function toolRows(u) {
  return [...u.tools.entries()].map(([name, t]) => ({
    name,
    count: t.count,
    errors: t.errors,
    p50: percentile(t.durations, 50),
    p95: percentile(t.durations, 95),
    total: t.durations.reduce((a, b) => a + b, 0),
  })).sort((a, b) => b.total - a.total || b.count - a.count);
}

export function runningCalls(u) {
  return [...u.calls.values()];
}

// ---------------------------------------------------------------- turns

export function turnStarted(u, at) {
  u.activity = { state: "thinking", tool: null, since: at };
}

export function turnEnded(u, at) {
  u.activity = { state: "idle", tool: null, since: at };
}

// ---------------------------------------------------------------- subagents

function agentEntry(u, id, at) {
  let a = u.agents.get(id);
  if (!a) {
    a = { id, type: "agent", description: "", status: "running", parentId: null, startedAt: at, endedAt: null, tools: new Map() };
    u.agents.set(id, a);
  }
  return a;
}

export function agentSpawned(u, { id, type, description, parentId, at }) {
  if (!id) return false;
  const a = agentEntry(u, id, at);
  a.type = type || a.type;
  a.description = description || a.description;
  a.parentId = parentId ?? a.parentId;
  a.startedAt = Math.min(a.startedAt, at);
  return true;
}

const ENDED = new Set(["completed", "failed", "killed"]);

// $.agent.list(): the engine's word on each agent's status.
export function applyAgentList(u, list, now) {
  let changed = false;
  for (const info of list ?? []) {
    const a = agentEntry(u, info.id, now);
    const was = a.status;
    a.type = info.type || a.type;
    a.description = info.description || a.description;
    a.parentId = info.parentId ?? a.parentId;
    a.status = info.status;
    if (ENDED.has(info.status) && !a.endedAt) a.endedAt = now;
    if (was !== a.status) changed = true;
  }
  return changed;
}

// Agents in tree order: each one followed by those it spawned, newest first
// at each level. Each row carries its depth and whether it is the last child.
export function agentTree(u) {
  const all = [...u.agents.values()];
  // An agent whose parent isn't known is drawn at the top level.
  const parentOf = (a) => (a.parentId && u.agents.has(a.parentId) ? a.parentId : null);
  const out = [];
  const walk = (pid, depth) => {
    const list = all.filter((a) => parentOf(a) === pid).sort((a, b) => b.startedAt - a.startedAt);
    list.forEach((a, i) => {
      out.push({ agent: a, depth, last: i === list.length - 1 });
      walk(a.id, depth + 1);
    });
  };
  walk(null, 0);
  return out;
}

export function agentCounts(u) {
  let running = 0;
  let done = 0;
  for (const a of u.agents.values()) {
    if (ENDED.has(a.status)) done++;
    else running++;
  }
  return { running, done };
}

export function isEnded(status) {
  return ENDED.has(status);
}

// The tool an agent used most: "Read ×14".
export function topTool(agent) {
  let best = null;
  for (const [name, n] of agent.tools) if (!best || n > best[1]) best = [name, n];
  return best ? `${best[0]} ×${best[1]}` : "";
}

files.hooks/github.mjs:
// The Git room's data: the local branch from `git status`, and pull requests,
// reviews, Actions runs, issues and Dependabot alerts from the `gh` CLI,
// signed in as the person already is. Nothing is stored and no token passes
// through here. `run(argv)` comes from the hooks module ($.process.run).

const PR_FIELDS = "number,title,state,isDraft,url,author,headRefName,reviewDecision,statusCheckRollup,updatedAt";
const PR_VIEW_FIELDS = `${PR_FIELDS},mergeable,mergeStateStatus,reviews,reviewRequests`;

export function emptyGit() {
  return {
    status: "idle",       // idle | loading | ok | no-gh | no-auth | no-repo | error
    error: "",
    fetchedAt: 0,
    stale: false,         // the last refresh failed: what's shown is older
    me: null,             // the gh login
    repo: null,           // { name, url }
    local: null,          // { branch, ahead, behind, changed }
    pr: null,             // this branch's pull request
    prs: [],              // open pull requests
    reviewMe: [],         // numbers of open PRs that ask for my review
    runs: [],             // recent Actions runs
    issues: [],           // open issues assigned to me
    alerts: null,         // Dependabot alerts, or null when not readable
  };
}

// ---------------------------------------------------------------- parsing

// `git status --porcelain=v2 --branch`
export function parseGitStatus(out) {
  const local = { branch: null, ahead: 0, behind: 0, changed: 0, upstream: null, unpushed: null };
  for (const line of String(out).split("\n")) {
    if (line.startsWith("# branch.head ")) local.branch = line.slice(14).trim();
    else if (line.startsWith("# branch.upstream ")) local.upstream = line.slice(18).trim();
    else if (line.startsWith("# branch.ab ")) {
      const m = /\+(\d+) -(\d+)/.exec(line);
      if (m) { local.ahead = Number(m[1]); local.behind = Number(m[2]); }
    } else if (/^[12u?] /.test(line)) local.changed++;
  }
  if (local.branch === "(detached)") local.branch = "detached";
  return local;
}

const FAILED = new Set(["FAILURE", "TIMED_OUT", "CANCELLED", "ACTION_REQUIRED", "STARTUP_FAILURE", "ERROR"]);

// A PR's checks as counts: passed, failed, still running.
export function checks(rollup) {
  const c = { pass: 0, fail: 0, pending: 0, total: 0 };
  for (const item of rollup ?? []) {
    c.total++;
    if (item.__typename === "StatusContext" || item.state) {
      if (item.state === "SUCCESS") c.pass++;
      else if (FAILED.has(item.state)) c.fail++;
      else c.pending++;
      continue;
    }
    if (item.status !== "COMPLETED") c.pending++;
    else if (FAILED.has(item.conclusion)) c.fail++;
    else c.pass++;
  }
  return c;
}

function prModel(p) {
  return {
    number: p.number,
    title: p.title ?? "",
    state: p.state ?? "OPEN",
    draft: !!p.isDraft,
    url: p.url,
    author: p.author?.login ?? "",
    branch: p.headRefName ?? "",
    decision: p.reviewDecision || null,     // APPROVED | CHANGES_REQUESTED | REVIEW_REQUIRED
    checks: checks(p.statusCheckRollup),
    updatedAt: Date.parse(p.updatedAt) || 0,
  };
}

// `gh pr view` adds who reviewed (each person's latest word) and who's asked.
export function parsePrView(p) {
  const pr = prModel(p);
  const latest = new Map();
  for (const r of p.reviews ?? []) {
    const who = r.author?.login;
    if (!who || r.state === "COMMENTED" || r.state === "PENDING") continue;
    latest.set(who, r.state);
  }
  pr.reviews = [...latest].map(([login, state]) => ({ login, state }));
  pr.requested = (p.reviewRequests ?? []).map((r) => r.login ?? r.name ?? r.slug).filter(Boolean);
  pr.mergeable = p.mergeable ?? "UNKNOWN";          // MERGEABLE | CONFLICTING | UNKNOWN
  pr.mergeState = p.mergeStateStatus ?? "UNKNOWN";  // CLEAN | BLOCKED | BEHIND | DIRTY | UNSTABLE | ...
  return pr;
}

export function parsePrList(list) {
  return (list ?? []).map(prModel);
}

// Recent runs, the newest of each workflow on each branch only: an older
// run that a newer one replaced (a failure since fixed) no longer counts.
export function parseRuns(list) {
  const seen = new Set();
  return (list ?? []).filter((r) => {
    const key = `${r.workflowName || r.name}\u0000${r.headBranch}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  }).map((r) => ({
    id: r.databaseId,
    name: r.workflowName || r.name || "workflow",
    branch: r.headBranch ?? "",
    status: r.status,                 // queued | in_progress | completed
    conclusion: r.conclusion || null, // success | failure | cancelled | skipped
    startedAt: Date.parse(r.createdAt) || 0,
    updatedAt: Date.parse(r.updatedAt) || 0,
    url: r.url,
  }));
}

export function parseIssues(list) {
  return (list ?? []).map((i) => ({
    number: i.number,
    title: i.title ?? "",
    url: i.url,
    labels: (i.labels ?? []).map((l) => l.name),
    updatedAt: Date.parse(i.updatedAt) || 0,
  }));
}

export function parseAlerts(list) {
  return (list ?? []).map((a) => ({
    number: a.number,
    pkg: a.dependency?.package?.name ?? a.security_vulnerability?.package?.name ?? "dependency",
    severity: a.security_advisory?.severity ?? a.security_vulnerability?.severity ?? "unknown",
    url: a.html_url,
  }));
}

// ---------------------------------------------------------------- fetching

const NO_AUTH = /gh auth login|not logged in|authentication|HTTP 401/i;
const NO_PR = /no pull requests found|no open pull requests/i;
const NO_REMOTE = /no git remotes|none of the git remotes|not a github|could not determine/i;

function json(out) {
  try { return JSON.parse(out || "null"); } catch { return null; }
}

// Everything the room shows, fetched in parallel. `prev` is the last good
// snapshot: on a failed refresh it stays, marked stale.
export async function fetchGit(run, prev = emptyGit()) {
  const next = { ...emptyGit(), me: prev.me };
  let status;
  try {
    status = await run(["git", "status", "--porcelain=v2", "--branch"]);
  } catch (err) {
    return { ...prev, status: "error", error: `git: ${err?.message ?? err}`, stale: prev.status === "ok" };
  }
  if (status.exitCode !== 0) {
    return /not a git repository/i.test(status.stderr)
      ? { ...emptyGit(), status: "no-repo" }
      : { ...prev, status: "error", error: firstLine(status.stderr) || "git status failed", stale: prev.status === "ok" };
  }
  next.local = parseGitStatus(status.stdout);
  // A branch that was never pushed has nothing to be ahead of: count its
  // commits past the main branch instead.
  if (!next.local.upstream && next.local.branch && next.local.branch !== "detached") {
    next.local.unpushed = await unpushed(run);
  }

  const gh = (args) => run(["gh", ...args]).then((r) => r, (err) => ({ thrown: err }));
  const [repo, me] = await Promise.all([
    gh(["repo", "view", "--json", "nameWithOwner,url"]),
    prev.me ? Promise.resolve(null) : gh(["api", "user", "--jq", ".login"]),
  ]);
  if (repo.thrown) return { ...emptyGit(), local: next.local, status: "no-gh" };
  if (repo.exitCode !== 0) {
    if (NO_AUTH.test(repo.stderr)) return { ...emptyGit(), local: next.local, status: "no-auth" };
    if (NO_REMOTE.test(repo.stderr)) return { ...emptyGit(), local: next.local, status: "ok", fetchedAt: Date.now(), error: "no GitHub remote" };
    return { ...prev, local: next.local, status: "error", error: firstLine(repo.stderr) || "gh failed", stale: prev.status === "ok" };
  }
  const r = json(repo.stdout);
  next.repo = { name: r?.nameWithOwner ?? "", url: r?.url ?? "" };
  if (me && me.exitCode === 0) next.me = me.stdout.trim() || null;

  const [view, list, mine, runs, issues, alerts] = await Promise.all([
    gh(["pr", "view", "--json", PR_VIEW_FIELDS]),
    gh(["pr", "list", "--state", "open", "--limit", "8", "--json", PR_FIELDS]),
    gh(["pr", "list", "--state", "open", "--search", "review-requested:@me", "--json", "number"]),
    gh(["run", "list", "--limit", "12", "--json", "databaseId,name,workflowName,headBranch,status,conclusion,createdAt,updatedAt,url"]),
    gh(["issue", "list", "--state", "open", "--assignee", "@me", "--limit", "6", "--json", "number,title,url,labels,updatedAt"]),
    gh(["api", "repos/{owner}/{repo}/dependabot/alerts?state=open&per_page=5"]),
  ]);
  const ok = (x) => !x.thrown && x.exitCode === 0;
  if (!ok(list)) {
    return { ...prev, local: next.local, repo: next.repo, status: "error", error: firstLine(list.stderr ?? list.thrown?.message) || "gh pr list failed", stale: prev.status === "ok" };
  }
  next.pr = ok(view) ? parsePrView(json(view.stdout) ?? {}) : null;
  if (!ok(view) && !NO_PR.test(view.stderr ?? "")) next.pr = prev.pr;   // a hiccup: keep what we had
  next.prs = parsePrList(json(list.stdout));
  next.reviewMe = ok(mine) ? (json(mine.stdout) ?? []).map((p) => p.number) : prev.reviewMe;
  next.runs = ok(runs) ? parseRuns(json(runs.stdout)) : prev.runs;
  next.issues = ok(issues) ? parseIssues(json(issues.stdout)) : prev.issues;
  // No access to alerts (not an admin, or turned off): leave the section out.
  next.alerts = ok(alerts) ? parseAlerts(json(alerts.stdout)) : null;
  next.status = "ok";
  next.fetchedAt = Date.now();
  return next;
}

async function unpushed(run) {
  for (const base of ["origin/HEAD", "origin/main", "origin/master"]) {
    try {
      const r = await run(["git", "rev-list", "--count", `${base}..HEAD`]);
      if (r.exitCode === 0) return Number(r.stdout.trim()) || 0;
    } catch { return null; }
  }
  return null;
}

function firstLine(text) {
  return String(text ?? "").trim().split("\n")[0].slice(0, 120);
}

// ---------------------------------------------------------------- what changed

// Toast-worthy changes between two good snapshots, as short lines.
export function diffGit(prev, next) {
  if (prev?.status !== "ok" || next?.status !== "ok" || !prev.fetchedAt) return [];
  const out = [];
  const a = prev.pr;
  const b = next.pr;
  if (a && b && a.number === b.number) {
    if (b.checks.fail > a.checks.fail) out.push(`✗ Checks failed on #${b.number}`);
    else if (a.checks.pending > 0 && b.checks.pending === 0 && b.checks.fail === 0 && b.checks.total) out.push(`✓ All checks passed on #${b.number}`);
    if (b.decision !== a.decision && b.decision === "APPROVED") out.push(`✓ #${b.number} was approved`);
    if (b.decision !== a.decision && b.decision === "CHANGES_REQUESTED") out.push(`● Changes requested on #${b.number}`);
    if (b.state !== a.state && b.state === "MERGED") out.push(`✓ #${b.number} was merged`);
    if (b.mergeable !== a.mergeable && b.mergeable === "CONFLICTING") out.push(`✗ #${b.number} has a merge conflict`);
  }
  for (const n of next.reviewMe) {
    if (prev.reviewMe.includes(n)) continue;
    const pr = next.prs.find((p) => p.number === n);
    out.push(`● ${pr?.author || "Someone"} asked for your review on #${n}${pr ? ` ${pr.title}` : ""}`);
  }
  return out;
}

// Needs a look: this branch's checks failed, or someone wants your review.
export function gitAttention(g) {
  if (g?.status !== "ok") return false;
  return (g.pr?.checks.fail ?? 0) > 0 || g.reviewMe.length > 0 || g.pr?.mergeable === "CONFLICTING";
}

export function ghStatusText(g) {
  switch (g.status) {
    case "no-gh": return "The Git room reads GitHub through the gh CLI. Install it (brew install gh), then gh auth login.";
    case "no-auth": return "gh isn't signed in. Run gh auth login in a terminal, then press r here.";
    case "no-repo": return "This session's folder isn't a git repository.";
    default: return "";
  }
}

files.hooks/sessions.mjs:
// Every Claude Code session on this computer, for the Agents room. Each
// session's mod sends a small heartbeat to its bridge, the bridge keeps it as
// a file next to the others', and every bridge reports the set back (a
// "sessions" event). Only what the room draws goes in: no prompts, no output.

import { agentTree, topTool } from "./metrics.mjs";

const FEED_SHARED = 12;

// This session's heartbeat, from its own figures.
export function heartbeat(u, { id, cwd, branch, now }) {
  const project = String(cwd ?? "").split("/").filter(Boolean).at(-1) ?? "session";
  return {
    v: 1,
    id,
    project,
    cwd,
    branch: branch ?? null,
    model: u.model,
    activity: u.activity,
    cost: u.cost?.usd ?? null,
    context: u.context?.percent ?? null,
    agents: agentTree(u).map(({ agent: a, depth, last }) => ({
      id: a.id, type: a.type, description: a.description, status: a.status,
      startedAt: a.startedAt, endedAt: a.endedAt, top: topTool(a), depth, last,
    })),
    feed: u.feed.slice(-FEED_SHARED).map((f) => ({
      key: f.key, tool: f.tool, agent: f.agentId ? (u.agents.get(f.agentId)?.type ?? "agent") : null,
      summary: f.summary, at: f.at, ms: f.ms, isError: f.isError, done: f.done,
    })),
    updatedAt: now,
  };
}

// What changed enough to send now (rather than at the next idle beat).
export function beatKey(hb) {
  return JSON.stringify([hb.activity, hb.agents.map((a) => a.status), hb.feed.at(-1)?.key, hb.feed.at(-1)?.done, Math.round((hb.cost ?? 0) * 100)]);
}

// Sessions in the order the room lists them: this one, then busy ones, then
// the rest by when they last did something.
export function orderSessions(own, others) {
  const list = [own, ...others.filter((s) => s && s.id !== own?.id)].filter(Boolean);
  const busy = (s) => ((s.activity?.state && s.activity.state !== "idle") || (s.agents ?? []).some((a) => !["completed", "failed", "killed"].includes(a.status)) ? 1 : 0);
  return list.sort((a, b) => (a === own ? -1 : b === own ? 1 : 0) || busy(b) - busy(a) || (b.activity?.since ?? 0) - (a.activity?.since ?? 0));
}

// One feed across sessions, newest last, each row naming its session.
export function mergedFeed(sessions, { filter = "all", ownId, limit = 12 } = {}) {
  const rows = [];
  for (const s of sessions) {
    if (filter === "here" && s.id !== ownId) continue;
    for (const f of s.feed ?? []) rows.push({ ...f, session: s.project, sessionId: s.id });
  }
  const kept = (filter === "errors" ? rows.filter((r) => r.isError) : rows).sort((a, b) => a.at - b.at);
  // A run of the same finished call (a subagent reading file after file
  // with one name) reads as one row with a count.
  const out = [];
  for (const r of kept) {
    const prev = out.at(-1);
    if (prev && prev.done && r.done && !r.isError && !prev.isError && prev.sessionId === r.sessionId
      && prev.agent === r.agent && prev.tool === r.tool && prev.summary === r.summary) {
      prev.times = (prev.times ?? 1) + 1;
      prev.at = r.at;
      prev.ms = r.ms;
      continue;
    }
    out.push({ ...r });
  }
  return out.slice(-limit);
}

files.hooks/share.mjs:
// Snippets: code or a diff from the session, shared to a room as one
// message. Plain logic: what to share, how it's titled, and whether it looks
// like it holds a secret.

export const MAX_SNIPPET = 8000;
export const MAX_SNIPPET_LINES = 200;
const LANG = /^[a-z0-9+#._-]{1,20}$/;

// The last fenced code block in Claude's latest reply that has one.
export function lastCodeBlock(messages) {
  for (let i = (messages?.length ?? 0) - 1; i >= 0; i--) {
    const m = messages[i];
    if (m?.role !== "assistant") continue;
    const blocks = [...String(m.text ?? "").matchAll(/```([^\n`]*)\n([\s\S]*?)```/g)];
    if (!blocks.length) continue;
    const [, info, body] = blocks.at(-1);
    return { body: body.replace(/\n$/, ""), lang: tag(info) };
  }
  return null;
}

// "ts" from "ts title=x.ts", lowercased; null for anything that isn't a short word.
export function tag(info) {
  const word = String(info ?? "").trim().split(/\s+/)[0].toLowerCase();
  return LANG.test(word) ? word : null;
}

export function looksLikeDiff(text) {
  return /^(diff --git |@@ -\d|--- a\/|\+\+\+ b\/)/m.test(String(text));
}

// "--- a/x", "+++ b/x", "--- /dev/null": git's file headers, not a removed
// line that happens to start with "--".
const FILE_HEADER = /^(---|\+\+\+) (a\/|b\/|\/dev\/null)/;

// Files touched and lines added and removed, read from a unified diff.
export function diffStats(body) {
  let files = 0, added = 0, removed = 0;
  for (const line of String(body).split("\n")) {
    if (line.startsWith("diff --git ")) files++;
    else if (FILE_HEADER.test(line)) continue;
    else if (line.startsWith("+")) added++;
    else if (line.startsWith("-")) removed++;
  }
  return { files, added, removed };
}

// The lines a person reads: tabs as two spaces, and for a diff each file as
// "▸ path", its hunks, and its changes with one unchanged line on each side
// (git gives three), without git's header lines.
export function displayLines(body, kind = "code") {
  const all = String(body).replace(/\t/g, "  ").split("\n");
  if (kind !== "diff") return all;
  const lines = all.flatMap((line) => {
    const file = /^diff --git a\/(.+?) b\//.exec(line);
    if (file) return [`▸ ${file[1]}`];
    return FILE_HEADER.test(line) || /^(index |new file mode|deleted file mode|similarity index|rename (from|to) )/.test(line) ? [] : [line];
  });
  const changed = (l) => l !== undefined && /^[+-]/.test(l);
  const marker = (l) => l.startsWith("▸ ") || l.startsWith("@@");
  return lines.filter((l, i) => marker(l) || changed(l) || changed(lines[i - 1]) || changed(lines[i + 1]));
}

export function lineCount(body) {
  return String(body).split("\n").length;
}

// A built-in room's snapshot is a code snippet tagged with the room's name.
export const SNAPSHOT_ICONS = { usage: "📊", git: "⎇", agents: "⟡" };

// "diff · 3 files +42 −7", "code · ts · 12 lines", "📊 Usage · opus-5.5 · 1h12m".
export function snippetTitle({ kind, lang, body }) {
  if (kind === "code" && SNAPSHOT_ICONS[lang]) return `${SNAPSHOT_ICONS[lang]} ${String(body).split("\n")[0].slice(0, 60)}`;
  if (kind === "diff") {
    const { files, added, removed } = diffStats(body);
    const where = files ? `${files} file${files === 1 ? "" : "s"} ` : "";
    return `diff · ${where}+${added} −${removed}`;
  }
  const n = lineCount(body);
  return ["code", lang, `${n} line${n === 1 ? "" : "s"}`].filter(Boolean).join(" · ");
}

// What a one-line view shows for a message: its text, or the snippet's title.
export function oneLine(m) {
  return !m.kind || m.kind === "text" ? m.body : `📎 ${snippetTitle(m)}`;
}

// Things that shouldn't leave the computer. Each match names what it looks
// like, for the warning.
const SECRETS = [
  [/\bsk-(?:ant-|proj-)?[A-Za-z0-9_-]{20,}/, "an API key"],
  [/\bsb_secret_[A-Za-z0-9_-]{10,}/, "a Supabase secret key"],
  [/\b(?:ghp|gho|ghs|github_pat)_[A-Za-z0-9_]{20,}/, "a GitHub token"],
  [/\bAKIA[0-9A-Z]{16}\b/, "an AWS access key"],
  [/\bxox[abprs]-[A-Za-z0-9-]{10,}/, "a Slack token"],
  [/-----BEGIN [A-Z ]*PRIVATE KEY-----/, "a private key"],
  [/^\+?\s*(?:export\s+)?[A-Z][A-Z0-9_]*(?:SECRET|TOKEN|PASSWORD|API_KEY|PRIVATE_KEY)[A-Z0-9_]*\s*=\s*\S{8,}/m, "a secret in an env file"],
];

export function findSecret(body) {
  for (const [pattern, what] of SECRETS) if (pattern.test(body)) return what;
  return null;
}

// Why a snippet can't be shared as it is, or null.
export function tooBig(body) {
  const lines = lineCount(body);
  if (lines > MAX_SNIPPET_LINES) return `that's ${lines} lines, more than ${MAX_SNIPPET_LINES}`;
  if (body.length > MAX_SNIPPET) return `that's ${body.length} characters, more than ${MAX_SNIPPET}`;
  return null;
}

files.hooks/sysviews.mjs:
// The built-in rooms, drawn from state alone: Usage (this session's context,
// limits, spend, tools and subagents), Git (the branch, pull requests,
// Actions, issues) and Agents (every session on this computer, and a live
// feed of tool calls). Each has a docked layout of cards, a compact one for
// the inline pane, a one-line summary for the band, and a plain-text
// snapshot for sharing to a chat room.

import { state } from "./state.mjs";
import { theme, level, nameColor } from "./theme.mjs";
import {
  cells, clip, fit, fmtTokens, fmtUsd, fmtDur, fmtSpan, relTime, age, resetLabel,
  bar, sparkline, meter, tiles, line, col, stackCards, CARD_GAP, LABEL_W,
} from "./widgets.mjs";
import {
  totalTokens, cacheRatio, burnRate, limitWindows, spendSeries, toolRows, agentTree, agentCounts, isEnded, topTool,
} from "./metrics.mjs";
import { gitAttention, ghStatusText } from "./github.mjs";
import { orderSessions, mergedFeed } from "./sessions.mjs";

export const SYS = {
  usage: { icon: "◔", label: "Usage", color: theme.usage },
  git: { icon: "⎇", label: "Git", color: theme.git },
  agents: { icon: "⟡", label: "Agents", color: theme.agents },
};

const SPIN = ["◐", "◓", "◑", "◒"];
const spin = (now) => SPIN[Math.floor(now / 1000) % SPIN.length];

// "claude-opus-5-5" → "opus-5.5"
export function shortModel(id) {
  if (!id) return "";
  return String(id).replace(/^claude-/, "").replace(/-\d{8}$/, "").replace(/-(\d+)-(\d+)$/, "-$1.$2");
}

// One rate-limit window's meter. Without a reading (it just reset) it says so.
function limitMeter(els, l, w) {
  const right = l.percentUsed == null ? "no data yet" : l.resetsAt ? `↻ ${resetLabel(l.resetsAt)}` : "";
  return meter(els, { key: `rl-${l.kind}`, label: limitName(l.kind), pct: l.percentUsed ?? undefined, width: w, right });
}

const LIMIT_NAMES = { five_hour: "5-hour", seven_day: "7-day", seven_day_opus: "7d opus", seven_day_sonnet: "7d sonnet", spend_limit: "Spend" };
function limitName(kind) {
  return LIMIT_NAMES[kind] ?? String(kind).replace(/_/g, " ");
}

// A rounded card like the chat's: a bold title, right-aligned meta (text or
// an element), the rows. Returns the node and the rows it takes.
function card(els, { key, title, color, meta, metaColor, metaNode, rows, grow = false }) {
  const { Box, Text } = els;
  const head = Box({ key: "head", flexDirection: "row", justifyContent: "space-between", gap: 1, children: [
    Text({ key: "title", bold: true, color, wrap: "truncate-end", children: title }),
    metaNode ?? (meta ? Text({ key: "meta", color: metaColor ?? theme.muted, wrap: "truncate-start", children: meta }) : null),
  ].filter(Boolean) });
  const body = grow
    ? [Box({ key: "body", flexDirection: "column", flexGrow: 1, overflow: "hidden", children: rows })]
    : rows;
  return Box({
    key, flexDirection: "column", borderStyle: "round", borderColor: theme.border, paddingX: 1,
    flexGrow: grow ? 1 : 0, flexShrink: grow ? 1 : 0, children: [head, ...body],
  });
}

const sized = (name, node, rowCount) => ({ name, node, height: 3 + rowCount });
const muted = (els, key, text) => els.Text({ key, color: theme.muted, wrap: "truncate-end", children: text });
const copyButton = (els, key, url, handlers) => (url ? { node: els.Button({ key, plain: true, dimColor: true, label: "⧉", onPress: () => handlers.onCopy?.(url) }) } : null);

// ---------------------------------------------------------------- Usage

function usageCard(els, w, handlers, now) {
  const u = state.usage;
  const rows = [];
  if (!u.measured) {
    rows.push(muted(els, "wait", "Waiting for the first reply from Claude…"));
  } else {
    const c = u.context ?? {};
    const right = c.tokens != null ? `${fmtTokens(c.tokens)}/${fmtTokens(c.window)}` : `${fmtTokens(c.window)} window`;
    rows.push(meter(els, { key: "ctx", label: u.showBreakdown ? "Context ▾" : "Context ▸", pct: c.percent, width: w, right, onPress: handlers.onToggleBreakdown }));
    if (u.showBreakdown) {
      const cats = (u.breakdown?.categories ?? []).filter((x) => !x.isDeferred && x.tokens > 0 && !/free space/i.test(x.name));
      if (!u.breakdown) rows.push(muted(els, "bd-wait", "  counting…"));
      for (const [i, x] of cats.slice(0, 6).entries()) {
        const pct = u.breakdown.maxTokens ? (x.tokens / u.breakdown.maxTokens) * 100 : 0;
        rows.push(meter(els, { key: `bd${i}`, label: `  ${x.name}`, pct, width: w, right: fmtTokens(x.tokens), color: theme.usage }));
      }
    }
    const windows = limitWindows(u);
    if (windows.length) {
      for (const l of windows) rows.push(limitMeter(els, l, w));
    } else {
      rows.push(muted(els, "nolimits", "No rate-limit windows on this account."));
    }
  }
  const meta = [shortModel(u.model), u.startedAt ? fmtSpan(now - u.startedAt) : null].filter(Boolean).join(" · ");
  return sized("Usage", card(els, { key: "usage", title: "USAGE", color: theme.usage, meta, rows }), rows.length);
}

function spendCard(els, w, now) {
  const u = state.usage;
  const series = spendSeries(u, now);
  const rate = burnRate(u, now);
  const cache = cacheRatio(u);
  const spark = series.some((v) => v > 0) ? `${sparkline(series)} last 1h` : "";
  const list = [
    { value: u.cost ? fmtUsd(u.cost.usd) : "–", sub: rate != null ? `+${fmtUsd(rate)}/h` : "this session", color: theme.usage },
    { value: fmtTokens(totalTokens(u)), sub: `${fmtTokens(u.tokens.output)} out`, color: undefined },
    { value: cache == null ? "–" : `${Math.round(cache)}%`, sub: "cache hits", color: cache == null ? theme.muted : cache >= 60 ? theme.online : cache >= 30 ? theme.amber : theme.error },
  ];
  return sized("Spend", card(els, { key: "spend", title: "SPEND", color: theme.usage, meta: spark, metaColor: theme.usage, rows: [tiles(els, list, w)] }), 2);
}

// The number columns, shared by the header and every row so they line up.
const TOOL_COLS = [["p50", 6], ["p95", 6], ["calls", 7], ["fail", 6]];
const TOOL_NUMS = TOOL_COLS.reduce((n, [, w]) => n + w, 0);
const toolHeader = () => TOOL_COLS.map(([h, w]) => fit(h, w, { right: true })).join("");

function toolsCard(els, w, max) {
  const { Box } = els;
  const list = toolRows(state.usage).slice(0, max);
  const rows = [];
  if (!list.length) rows.push(muted(els, "none", "No tool calls yet."));
  const NAME = Math.min(14, Math.max(8, ...list.map((t) => cells(t.name) + 1)));
  const barW = Math.max(3, w - NAME - TOOL_NUMS);
  const top = Math.max(...list.map((t) => t.total), 1);
  const [[, w50], [, w95], [, wCalls], [, wFail]] = TOOL_COLS;
  for (const t of list) {
    const fill = bar((t.total / top) * 100, barW).fill || "╸";   // even a quick tool gets a mark
    rows.push(Box({ key: `t-${t.name}`, flexDirection: "row", children: [
      col(els, "n", clip(t.name, NAME - 1), NAME),
      Box({ key: "b", width: barW, flexShrink: 1, minWidth: 0, overflow: "hidden", children: [
        els.Text({ key: "t", color: theme.usage, wrap: "truncate-end", children: fill }),
      ] }),
      col(els, "p50", fmtDur(t.p50), w50, { right: true }),
      col(els, "p95", fmtDur(t.p95), w95, { right: true, color: theme.muted }),
      col(els, "c", String(t.count), wCalls, { right: true }),
      col(els, "e", String(t.errors), wFail, { right: true, bold: t.errors > 0, color: t.errors ? theme.error : theme.muted }),
    ] }));
  }
  // The header ends at the card's right edge, as the rows do: each label sits over its column.
  const header = list.length
    ? Box({ key: "meta", flexDirection: "row", flexShrink: 0, children: TOOL_COLS.map(([h, cw]) => col(els, h, h, cw, { right: true, color: theme.muted })) })
    : null;
  return sized("Tools", card(els, { key: "tools", title: "TOOLS", color: theme.usage, metaNode: header, rows }), rows.length);
}

function agentGlyph(status, now) {
  if (status === "completed") return { g: "✓", color: theme.online };
  if (status === "failed") return { g: "✗", color: theme.error };
  if (status === "killed") return { g: "⊘", color: theme.muted };
  if (status === "idle" || status === "waiting" || status === "pending") return { g: "○", color: theme.agents };
  return { g: spin(now), color: theme.agents };
}

function agentRow(els, key, a, { indent = "", now }) {
  const st = agentGlyph(a.status, now);
  const took = (a.endedAt ?? now) - a.startedAt;
  return line(els, key, [
    indent ? { text: indent, color: theme.muted } : null,
    { text: `${st.g} `, color: st.color },
    { text: clip(a.type, 9), width: 10, bold: true },
    { text: a.description, grow: true },
    { text: ` ${isEnded(a.status) ? "done" : fmtDur(took)}`, color: theme.muted },
    a.top ? { text: `  ${a.top}`, color: theme.muted } : null,
  ]);
}

function subagentsCard(els, max, now) {
  const tree = agentTree(state.usage);
  const { running, done } = agentCounts(state.usage);
  const rows = tree.slice(0, max).map(({ agent: a, depth, last }) => agentRow(els, `a-${a.id}`, { ...a, top: topTool(a) }, {
    indent: depth ? `${"   ".repeat(depth - 1)}${last ? "└─ " : "├─ "}` : "", now,
  }));
  if (tree.length > max) rows.push(muted(els, "more", `+${tree.length - max} more`));
  if (!rows.length) rows.push(muted(els, "none", "None yet. They show up here as Claude starts them."));
  const meta = running || done ? `${running} running · ${done} done` : "";
  return sized("Subagents", card(els, { key: "subagents", title: "SUBAGENTS", color: theme.usage, meta, metaColor: running ? theme.agents : theme.muted, rows }), rows.length);
}

function usageDock(els, w, capacity, handlers, now) {
  return stackCards(els, [
    usageCard(els, w, handlers, now),
    spendCard(els, w, now),
    toolsCard(els, w, 5),
    subagentsCard(els, 4, now),
  ], capacity);
}

// ---------------------------------------------------------------- Git

function ago(g, now) {
  if (g.status === "loading" && !g.fetchedAt) return { text: "loading…", color: theme.muted };
  if (!g.fetchedAt) return { text: "", color: theme.muted };
  return { text: `${g.stale ? "⚠ " : ""}updated ${relTime(g.fetchedAt, now)}`, color: g.stale ? theme.amber : theme.muted };
}

// Where the branch stands against its remote: "↑2 ↓1", or "local" (with its
// commits past main, "↑3 local") when it has no remote branch yet. Then the
// working tree: "● 23 changed" or "clean".
function syncPieces(l) {
  if (!l) return [];
  const sync = l.upstream
    ? [
      { text: `↑${l.ahead}`, color: l.ahead ? theme.sky : theme.muted, bold: l.ahead > 0 },
      { text: " " },
      { text: `↓${l.behind}`, color: l.behind ? theme.amber : theme.muted, bold: l.behind > 0 },
    ]
    : [{ text: l.unpushed ? `↑${l.unpushed} local` : "local", color: l.unpushed ? theme.amber : theme.muted }];
  const tree = l.changed
    ? { text: `● ${l.changed} changed`, color: theme.amber }
    : { text: "clean", color: theme.muted };
  return { sync, tree };
}

function checksPieces(c) {
  if (!c.total) return [{ text: "no checks", color: theme.muted }];
  return [
    { text: `✓ ${c.pass}`, color: c.pass ? theme.online : theme.muted },
    { text: `  ● ${c.pending}${c.pending ? " running" : ""}`, color: c.pending ? theme.amber : theme.muted },
    { text: `  ✗ ${c.fail}`, color: c.fail ? theme.error : theme.muted },
  ];
}

function mergePiece(pr) {
  if (pr.state === "MERGED") return { text: "merged ✓", color: theme.agents };
  if (pr.state === "CLOSED") return { text: "closed", color: theme.muted };
  if (pr.mergeable === "CONFLICTING" || pr.mergeState === "DIRTY") return { text: "conflict ✗", color: theme.error };
  if (pr.mergeState === "BEHIND") return { text: "behind base", color: theme.amber };
  if (pr.mergeState === "BLOCKED") return { text: "blocked", color: theme.amber };
  if (pr.mergeState === "CLEAN" || pr.mergeable === "MERGEABLE") return { text: "mergeable ✓", color: theme.online };
  return { text: "merge ?", color: theme.muted };
}

function prState(pr) {
  if (pr.state === "MERGED") return { text: "merged", color: theme.agents };
  if (pr.state === "CLOSED") return { text: "closed", color: theme.muted };
  if (pr.draft) return { text: "draft", color: theme.muted };
  return { text: "open", color: theme.git };
}

// The short status a PR row ends in, most urgent first.
function prPill(pr, g) {
  if (g.reviewMe.includes(pr.number)) return { text: "● you", color: theme.amber };
  if (pr.checks.fail) return { text: "✗ CI", color: theme.error };
  if (pr.decision === "CHANGES_REQUESTED") return { text: "● changes", color: theme.amber };
  if (pr.checks.pending) return { text: "● CI", color: theme.amber };
  if (pr.draft) return { text: "draft", color: theme.muted };
  if (pr.decision === "APPROVED") return { text: "✓ approved", color: theme.online };
  if (pr.checks.total) return { text: "✓ CI", color: theme.online };
  return { text: "", color: theme.muted };
}

function repoCard(els, handlers, now) {
  const g = state.git;
  const l = g.local;
  const rows = [];
  if (l) {
    const { sync, tree } = syncPieces(l);
    rows.push(line(els, "branch", [
      { text: `⎇ ${l.branch ?? "?"}`, bold: true, color: theme.git },
      { text: "  " },
      ...sync,
      { text: "  " },
      { ...tree, grow: true },
      { node: els.Button({ key: "refresh", plain: true, dimColor: true, label: "↻", onPress: () => handlers.onRefresh?.() }) },
    ]));
  }
  const help = ghStatusText(g);
  if (help) rows.push(els.Text({ key: "help", color: theme.warn, wrap: "wrap", children: help }));
  else if (g.error && (g.stale || !g.fetchedAt || g.error === "no GitHub remote")) rows.push(muted(els, "err", g.error === "no GitHub remote" ? "No GitHub remote: only the local branch shows here." : `⚠ ${g.error}`));
  if (!rows.length) rows.push(muted(els, "wait", "Reading the repository…"));
  const when = ago(g, now);
  const helpRows = help ? Math.ceil(cells(help) / 44) : 0;
  return sized("Repo", card(els, { key: "repo", title: g.repo?.name || "REPOSITORY", color: theme.git, meta: when.text, metaColor: when.color, rows }), rows.length + Math.max(0, helpRows - 1));
}

function branchCard(els, handlers) {
  const g = state.git;
  if (g.status !== "ok" || !g.repo) return null;
  const pr = g.pr;
  if (!pr) {
    return sized("This branch", card(els, { key: "branch", title: "THIS BRANCH", color: theme.git, meta: "no pull request", rows: [
      muted(els, "none", g.local?.ahead ? "Pushed commits, no PR yet. Open one with gh pr create." : "No pull request for this branch."),
    ] }), 1);
  }
  const st = prState(pr);
  const reviewers = [
    ...pr.reviews.map((r) => ({ text: `${r.state === "APPROVED" ? "✓" : r.state === "CHANGES_REQUESTED" ? "✗" : "●"} ${r.login}`, color: r.state === "APPROVED" ? theme.online : r.state === "CHANGES_REQUESTED" ? theme.error : theme.muted })),
    ...pr.requested.filter((x) => !pr.reviews.some((r) => r.login === x)).map((x) => ({ text: `● ${x}`, color: theme.amber })),
  ];
  const rows = [
    line(els, "title", [{ text: pr.title, grow: true, bold: true }]),
    line(els, "checks", [...checksPieces(pr.checks), { text: "", grow: true }, mergePiece(pr)]),
    line(els, "reviews", [
      { text: "reviews ", color: theme.muted },
      ...(reviewers.length ? reviewers.flatMap((r, i) => [i ? { text: "  " } : null, r]) : [{ text: pr.decision === "REVIEW_REQUIRED" ? "needed, none asked yet" : "none", color: theme.muted }]),
    ]),
    els.Box({ key: "actions", flexDirection: "row", gap: 2, children: [
      els.Button({ key: "copy-pr", label: "Copy link", onPress: () => handlers.onCopy?.(pr.url) }),
    ] }),
  ];
  return sized("This branch", card(els, { key: "branch", title: "THIS BRANCH", color: theme.git, meta: `PR #${pr.number} · ${st.text}`, metaColor: st.color, rows }), rows.length);
}

function prsCard(els, handlers, max, now) {
  const g = state.git;
  if (g.status !== "ok" || !g.repo) return null;
  const list = g.prs.filter((p) => p.number !== g.pr?.number)
    .sort((a, b) => Number(g.reviewMe.includes(b.number)) - Number(g.reviewMe.includes(a.number)) || b.updatedAt - a.updatedAt);
  const rows = list.slice(0, max).map((p) => {
    const pill = prPill(p, g);
    return line(els, `pr-${p.number}`, [
      { text: `#${p.number}`, width: 6, color: theme.muted },
      { text: p.title, grow: true },
      { text: clip(pill.text, 10), width: 11, right: true, color: pill.color },
      { text: clip(age(p.updatedAt, now), 4), width: 5, right: true, color: theme.muted },
      { text: " " },
      copyButton(els, "copy", p.url, handlers),
    ]);
  });
  if (list.length > max) rows.push(muted(els, "more", `+${list.length - max} more`));
  if (!rows.length) rows.push(muted(els, "none", "No other open pull requests."));
  const meta = `${g.prs.length} open${g.reviewMe.length ? ` · ${g.reviewMe.length} for you` : ""}`;
  return sized("Pull requests", card(els, { key: "prs", title: "PULL REQUESTS", color: theme.git, meta, metaColor: g.reviewMe.length ? theme.amber : theme.muted, rows }), rows.length);
}

function runGlyph(r, now) {
  if (r.status !== "completed") return { g: spin(now), color: theme.amber };
  if (r.conclusion === "success") return { g: "✓", color: theme.online };
  if (r.conclusion === "failure" || r.conclusion === "timed_out" || r.conclusion === "startup_failure") return { g: "✗", color: theme.error };
  return { g: "⊘", color: theme.muted };
}

function runsCard(els, handlers, max, now) {
  const g = state.git;
  if (g.status !== "ok" || !g.repo) return null;
  const rows = g.runs.slice(0, max).map((r) => {
    const st = runGlyph(r, now);
    const when = r.status === "completed" ? age(r.updatedAt, now) : `${r.status === "queued" ? "queued" : "running"} ${fmtDur(now - r.startedAt)}`;
    return line(els, `run-${r.id}`, [
      { text: `${st.g} `, color: st.color },
      { text: clip(r.name, 12), width: 13, bold: true },
      { text: r.branch, color: theme.muted, grow: true },
      { text: ` ${when} `, color: r.status === "completed" ? theme.muted : theme.amber },
      copyButton(els, "copy", r.url, handlers),
    ]);
  });
  if (!rows.length) rows.push(muted(els, "none", "No workflow runs."));
  const failing = g.runs.filter((r) => r.status === "completed" && runGlyph(r, now).g === "✗").length;
  const running = g.runs.filter((r) => r.status !== "completed").length;
  const meta = [running ? `${running} running` : null, failing ? `${failing} failed` : null].filter(Boolean).join(" · ");
  return sized("Actions", card(els, { key: "runs", title: "ACTIONS", color: theme.git, meta, metaColor: failing ? theme.error : running ? theme.amber : theme.muted, rows }), rows.length);
}

const SEVERITY = { critical: theme.error, high: theme.error, medium: theme.amber, moderate: theme.amber, low: theme.muted };

function issuesCard(els, handlers, max, now) {
  const g = state.git;
  if (g.status !== "ok" || !g.repo) return null;
  const rows = [];
  for (const i of g.issues.slice(0, max)) {
    rows.push(line(els, `is-${i.number}`, [
      { text: `#${i.number}`, width: 6, color: theme.muted },
      { text: i.title, grow: true },
      i.labels[0] ? { text: ` ${clip(i.labels[0], 12)}`, color: theme.agents } : null,
      { text: clip(age(i.updatedAt, now), 4), width: 5, right: true, color: theme.muted },
      { text: " " },
      copyButton(els, "copy", i.url, handlers),
    ]));
  }
  for (const a of (g.alerts ?? []).slice(0, Math.max(1, max - rows.length))) {
    rows.push(line(els, `al-${a.number}`, [
      { text: "⚠ ", color: SEVERITY[a.severity] ?? theme.amber },
      { text: a.pkg, bold: true, grow: true },
      { text: ` ${a.severity} `, color: SEVERITY[a.severity] ?? theme.amber },
      copyButton(els, "copy", a.url, handlers),
    ]));
  }
  if (!rows.length) rows.push(muted(els, "none", "No issues assigned to you."));
  const nAlerts = g.alerts?.length ?? 0;
  const meta = `${g.issues.length} assigned${nAlerts ? ` · ${nAlerts} ⚠` : ""}`;
  return sized("Issues", card(els, { key: "issues", title: "ISSUES & ALERTS", color: theme.git, meta, metaColor: nAlerts ? theme.amber : theme.muted, rows }), rows.length);
}

function gitDock(els, w, capacity, handlers, now) {
  return stackCards(els, [
    repoCard(els, handlers, now),
    branchCard(els, handlers),
    prsCard(els, handlers, 4, now),
    runsCard(els, handlers, 3, now),
    issuesCard(els, handlers, 3, now),
  ], capacity);
}

// ---------------------------------------------------------------- Agents

function allSessions() {
  return orderSessions(state.self, state.sessions);
}

// Subagents of a session still at work.
const liveAgents = (s) => (s.agents ?? []).filter((a) => !isEnded(a.status)).length;
// A session is busy while its turn runs or any of its agents does: a turn
// can end with a background agent still at work.
const sessionBusy = (s) => (s.activity?.state && s.activity.state !== "idle") || liveAgents(s) > 0;

function activityPieces(s, now) {
  const a = s.activity ?? { state: "idle" };
  const live = liveAgents(s);
  const since = a.since ? now - a.since : 0;
  const tail = [s.cost != null ? fmtUsd(s.cost) : null, s.context != null ? `ctx ${Math.round(s.context)}%` : null].filter(Boolean).join(" · ");
  const head = a.state === "tool" ? { text: `running ${a.tool} · ${fmtDur(since)}`, color: theme.agents }
    : a.state === "thinking" ? { text: `thinking · ${fmtDur(since)}`, color: theme.agents }
      : live ? { text: `waiting on ${live} agent${live === 1 ? "" : "s"}`, color: theme.agents }
        : { text: `idle${a.since ? ` ${age(a.since, now)}` : ""}`, color: theme.muted };
  return [{ text: "  " }, head, tail ? { text: ` · ${tail}`, color: theme.muted, grow: true } : { text: "", grow: true }];
}

function sessionRows(els, s, handlers, now, maxAgents) {
  const here = s.id === state.sessionId;
  const busy = sessionBusy(s);
  const color = nameColor(s.id);
  const folded = state.collapsed.has(s.id);
  const agents = s.agents ?? [];
  const live = agents.filter((a) => !isEnded(a.status)).length;
  const rows = [line(els, `s-${s.id}`, [
    { text: `${busy ? "●" : "○"} `, color: busy ? color : theme.muted },
    { text: s.project, bold: true, color },
    here ? { text: " (here)", color: theme.muted } : null,
    { text: s.branch ? `  ${s.branch}` : "", color: theme.muted, grow: true },
    { text: ` ${shortModel(s.model)} `, color: theme.muted },
    agents.length
      ? { node: els.Button({ key: "fold", plain: true, dimColor: true, label: folded ? `▸${live || agents.length}` : "▾", onPress: () => handlers.onToggleSession?.(s.id) }) }
      : { text: " " },   // keeps the model column in line with rows that have the fold mark
  ]), line(els, `sa-${s.id}`, activityPieces(s, now))];
  if (!folded) {
    const shown = agents.slice(0, maxAgents);
    for (const a of shown) {
      const indent = `  ${"   ".repeat(a.depth ?? 0)}${a.last || a === shown.at(-1) ? "└─ " : "├─ "}`;
      rows.push(agentRow(els, `ag-${s.id}-${a.id}`, a, { indent, now }));
    }
    if (agents.length > maxAgents) rows.push(muted(els, `agm-${s.id}`, `     +${agents.length - maxAgents} more`));
  }
  return rows;
}

function sessionsCard(els, handlers, maxRows, now) {
  const list = allSessions();
  const rows = [];
  for (const s of list) {
    const next = sessionRows(els, s, handlers, now, s.id === state.sessionId ? 4 : 2);
    if (rows.length && rows.length + next.length > maxRows) {
      rows.push(muted(els, "more", `+${list.length - list.indexOf(s)} more sessions`));
      break;
    }
    rows.push(...next);
  }
  if (!rows.length) rows.push(muted(els, "none", "Starting…"));
  const meta = `${list.length} on this computer`;
  return sized("Sessions", card(els, { key: "sessions", title: "SESSIONS", color: theme.agents, meta, rows }), rows.length);
}

const FILTERS = { all: "all", here: "here", errors: "errors" };

function feedRow(els, f, w, now) {
  const t = new Date(f.at);
  const clock = `${String(t.getHours()).padStart(2, "0")}:${String(t.getMinutes()).padStart(2, "0")}:${String(t.getSeconds()).padStart(2, "0")}`;
  const who = f.agent ? ` ↳ ${f.agent}` : f.session;
  const end = f.done ? (f.isError ? { text: " ✗", color: theme.error } : { text: " ✓", color: theme.online }) : { text: ` ${spin(now)}`, color: theme.agents };
  return line(els, `f-${f.sessionId}-${f.key}`, [
    w >= 46 ? { text: `${clock} `, color: theme.muted } : null,
    { text: clip(who, w >= 46 ? 11 : 9), width: w >= 46 ? 12 : 10, color: f.agent ? theme.muted : nameColor(f.sessionId) },
    { text: clip(f.tool, 6), width: 7, bold: true },
    { text: f.summary || "", color: theme.muted, grow: true },
    f.times > 1 ? { text: ` ×${f.times}`, color: theme.agents } : null,
    { text: ` ${f.done ? fmtDur(f.ms) : fmtDur(now - f.at)}`, color: f.done ? theme.muted : theme.agents },
    end,
  ]);
}

function feedCard(els, w, rowsLeft, handlers, now) {
  const rows = mergedFeed(allSessions(), { filter: state.feedFilter, ownId: state.sessionId, limit: Math.max(1, rowsLeft) })
    .map((f) => feedRow(els, f, w, now));
  if (!rows.length) rows.push(muted(els, "none", state.feedFilter === "errors" ? "No failed tool calls." : "Tool calls show up here as they run."));
  const metaNode = els.Button({ key: "filter", plain: true, dimColor: true, label: `${FILTERS[state.feedFilter]} ▾`, onPress: () => handlers.onCycleFilter?.() });
  return { name: "Live", node: card(els, { key: "feed", title: "LIVE", color: theme.agents, metaNode, rows, grow: true }), height: 3 + Math.min(rows.length, 1) };
}

function agentsDock(els, w, capacity, handlers, now) {
  const sessions = sessionsCard(els, handlers, Math.max(3, Math.floor((capacity - 4) * 0.55)), now);
  const left = capacity - sessions.height - CARD_GAP - 3;
  return stackCards(els, [sessions, feedCard(els, w, left, handlers, now)], capacity);
}

// ---------------------------------------------------------------- entry points

// The docked pane's body for a built-in room: cards within `capacity` rows.
export function sysDock(els, view, width, capacity, handlers, now = Date.now()) {
  const w = Math.max(20, width - 4);   // inside a card's border and padding
  if (view === "usage") return usageDock(els, w, capacity, handlers, now);
  if (view === "git") return gitDock(els, w, capacity, handlers, now);
  return agentsDock(els, w, capacity, handlers, now);
}

// The inline pane: a few lines, no cards.
export function sysInline(els, view, width, handlers, now = Date.now()) {
  const { Text } = els;
  const w = Math.max(20, width);
  const meta = SYS[view];
  const head = (text, right) => line(els, "head", [
    { text: `${meta.icon} ${meta.label}`, bold: true, color: meta.color },
    { text: text ? `  ${text}` : "", color: theme.muted, grow: true },
    right ? { text: right, color: theme.muted } : null,
  ]);
  if (view === "usage") {
    const u = state.usage;
    const parts = [head([shortModel(u.model), u.startedAt ? fmtSpan(now - u.startedAt) : null].filter(Boolean).join(" · "))];
    if (!u.measured) return [...parts, muted(els, "wait", "Waiting for the first reply from Claude…")];
    const c = u.context ?? {};
    parts.push(meter(els, { key: "ctx", label: "Context", pct: c.percent, width: w, right: c.tokens != null ? `${fmtTokens(c.tokens)}/${fmtTokens(c.window)}` : c.window ? `${fmtTokens(c.window)} window` : "" }));
    for (const l of limitWindows(u).slice(0, 2)) parts.push(limitMeter(els, l, w));
    const cache = cacheRatio(u);
    const running = agentCounts(u).running;
    parts.push(line(els, "spend", [
      { text: "Spend", width: LABEL_W, color: theme.muted },
      { text: u.cost ? fmtUsd(u.cost.usd) : "–", bold: true, color: theme.usage },
      { text: "  ·  ", color: theme.muted },
      { text: fmtTokens(totalTokens(u)), bold: true },
      { text: " tokens  ·  ", color: theme.muted },
      { text: cache == null ? "–" : `${Math.round(cache)}%`, bold: true, color: cache == null ? theme.muted : cache >= 60 ? theme.online : cache >= 30 ? theme.amber : theme.error },
      { text: " cache hits", color: theme.muted },
      running ? { text: `  ·  ⟡ ${running} running`, color: theme.agents } : null,
    ]));
    return parts;
  }
  if (view === "git") {
    const g = state.git;
    const l = g.local;
    const parts = [head("", ago(g, now).text)];
    if (l) {
      const { sync, tree } = syncPieces(l);
      parts.push(line(els, "branch", [{ text: `⎇ ${l.branch ?? "?"}`, bold: true, color: theme.git }, { text: "  " }, ...sync, { text: "  " }, { ...tree, grow: true }]));
    }
    const help = ghStatusText(g);
    if (help) return [...parts, Text({ key: "help", color: theme.warn, wrap: "wrap", children: help })];
    if (g.pr) {
      const c = g.pr.checks;
      parts.push(line(els, "pr", [{ text: `#${g.pr.number} `, color: theme.git, bold: true }, { text: g.pr.title, grow: true }, { text: ` ✓${c.pass} ●${c.pending} ✗${c.fail}`, color: c.fail ? theme.error : c.pending ? theme.amber : theme.online }]));
    }
    for (const p of g.prs.filter((p) => p.number !== g.pr?.number).slice(0, 3)) {
      const pill = prPill(p, g);
      parts.push(line(els, `pr-${p.number}`, [{ text: `#${p.number}`, width: 6, color: theme.muted }, { text: p.title, grow: true }, { text: ` ${pill.text}`, color: pill.color }]));
    }
    return parts;
  }
  const list = allSessions();
  const parts = [head(`${list.length} session${list.length === 1 ? "" : "s"}`)];
  for (const s of list.slice(0, 4)) {
    const live = (s.agents ?? []).filter((a) => !isEnded(a.status)).length;
    parts.push(line(els, `s-${s.id}`, [
      { text: `${sessionBusy(s) ? "●" : "○"} `, color: sessionBusy(s) ? nameColor(s.id) : theme.muted },
      { text: clip(s.project, 14), width: 15, bold: true, color: nameColor(s.id) },
      ...activityPieces(s, now).slice(1),
      live ? { text: ` ⟡${live}`, color: theme.agents } : null,
    ]));
  }
  return parts;
}

// How full the context is, as weather (from token-weather, the
// claude-code-playground mod): single-width symbols that line up in any font.
const FORECAST = [
  { upTo: 25, icon: "☀", word: "Clear", color: theme.amber },
  { upTo: 50, icon: "☁", word: "Cloudy", color: theme.usage },
  { upTo: 75, icon: "☂", word: "Showers", color: "#6FC2B5" },
  { upTo: 90, icon: "☇", word: "Storm", color: theme.agents },
  { upTo: Infinity, icon: "↯", word: "Compact soon", color: theme.error },
];
export function forecast(pct) {
  return FORECAST.find((f) => pct < f.upTo) ?? FORECAST.at(-1);
}

// The band's line for a built-in room, as colored pieces, fitted to `width`
// cells. For Usage: "☂ Showers 67% 134k/200k ▁▂▅█ ▲+98k · 5-hour 12% ·
// spent $1.21": the context as a forecast once measured, the 5-hour window,
// and the spend once there is some.
export function sysBandPieces(view, width = 0) {
  const sep = { text: " · ", color: theme.muted };
  const join = (list) => list.filter(Boolean).flatMap((p, i) => (i ? [sep, ...p] : p));
  const figure = (label, pct) => [{ text: `${label} `, color: theme.muted }, { text: `${Math.round(pct)}%`, color: level(pct), bold: true }];
  if (view === "usage") {
    const u = state.usage;
    const c = u.context;
    // The forecast, then the 5-hour window and the spend. On a narrow band
    // the turn's delta goes first, then the chart, then the token count.
    const weather = (detail) => {
      if (c?.percent == null) return null;
      const f = forecast(c.percent);
      const hist = u.ctxHistory;
      const delta = hist.length >= 2 ? hist.at(-1) - hist.at(-2) : 0;
      return [
        { text: `${f.icon} ${f.word} `, color: f.color, bold: true },
        { text: `${Math.round(c.percent)}%`, color: f.color, bold: true },
        detail >= 1 && c.tokens != null ? { text: ` ${fmtTokens(c.tokens)}/${fmtTokens(c.window)}`, color: theme.muted } : null,
        detail >= 2 && hist.length >= 2 ? { text: ` ${sparkline(hist, 12)}`, color: f.color } : null,
        detail >= 3 && delta ? { text: delta > 0 ? ` ▲+${fmtTokens(delta)}` : ` ▼${fmtTokens(-delta)}`, color: theme.muted } : null,
      ].filter(Boolean);
    };
    const five = limitWindows(u).find((l) => l.kind === "five_hour");
    const tail = [
      five ? (five.percentUsed == null
        ? [{ text: "5-hour ", color: theme.muted }, { text: "–", color: theme.muted }]
        : figure("5-hour", five.percentUsed)) : null,
      u.cost?.usd > 0 ? [{ text: "spent ", color: theme.muted }, { text: fmtUsd(u.cost.usd), color: theme.usage, bold: true }] : null,
    ];
    let pieces = [];
    for (let detail = 3; detail >= 0; detail--) {
      pieces = join([weather(detail), ...tail]);
      if (!width || cells(pieces.map((p) => p.text).join("")) <= width) break;
    }
    return pieces.length ? pieces : [{ text: "waiting for the first reply", color: theme.muted }];
  }
  if (view === "git") {
    const g = state.git;
    if (g.status === "no-repo") return [{ text: "not a git repository", color: theme.warn }];
    const pr = g.pr;
    // git works without gh: the branch shows either way.
    return join([
      g.local?.branch ? [{ text: g.local.branch, color: theme.git, bold: true }] : null,
      g.local ? syncPieces(g.local).sync : null,
      g.local ? [syncPieces(g.local).tree] : null,
      ghStatusText(g) ? [{ text: "gh isn't set up", color: theme.warn }] : null,
      pr ? [{ text: `#${pr.number} `, color: theme.muted }, ...checksPieces(pr.checks).map((p) => ({ ...p, text: p.text.replace(" running", "") }))] : null,
      g.reviewMe.length ? [{ text: `${g.reviewMe.length} review${g.reviewMe.length === 1 ? "" : "s"} for you`, color: theme.amber }] : null,
    ]);
  }
  const list = allSessions();
  const running = list.reduce((n, s) => n + (s.agents ?? []).filter((a) => !isEnded(a.status)).length, 0);
  return join([
    [{ text: `${list.length} session${list.length === 1 ? "" : "s"}`, color: theme.muted }],
    [{ text: `${running} agent${running === 1 ? "" : "s"} running`, color: running ? theme.agents : theme.muted }],
  ]);
}

// The same as plain text.
export function sysBandText(view) {
  return sysBandPieces(view).map((p) => p.text).join("");
}

// A tab's badge: what's worth a glance from another room.
export function sysBadge(view) {
  if (view === "git" && gitAttention(state.git)) return { text: "●", color: theme.error };
  if (view === "agents") {
    const n = allSessions().reduce((k, s) => k + (s.agents ?? []).filter((a) => !isEnded(a.status)).length, 0);
    if (n) return { text: String(n), color: theme.agents };
  }
  if (view === "usage" && (state.usage.context?.percent ?? 0) >= 80) return { text: `${Math.round(state.usage.context.percent)}%`, color: level(state.usage.context.percent) };
  return null;
}

// ---------------------------------------------------------------- snapshots

const textBar = (pct, width) => {
  const { fill, track } = bar(pct, width);
  return fill + track;
};

// A built-in room as plain text, for a snippet card in a chat room.
export function snapshotText(view, now = Date.now()) {
  const W = 20;
  const out = [];
  if (view === "usage") {
    const u = state.usage;
    out.push(`Usage · ${[shortModel(u.model), u.startedAt ? fmtSpan(now - u.startedAt) : null].filter(Boolean).join(" · ")}`);
    if (u.context) out.push(`${fit("Context", LABEL_W)}${textBar(u.context.percent ?? 0, W)} ${fit(`${Math.round(u.context.percent ?? 0)}%`, 4, { right: true })}  ${fmtTokens(u.context.tokens)}/${fmtTokens(u.context.window)}`);
    for (const l of limitWindows(u)) {
      out.push(`${fit(limitName(l.kind), LABEL_W)}${textBar(l.percentUsed ?? 0, W)} ${fit(l.percentUsed == null ? "–" : `${Math.round(l.percentUsed)}%`, 4, { right: true })}`);
    }
    const cache = cacheRatio(u);
    const rate = burnRate(u, now);
    out.push(`Spend    ${u.cost ? fmtUsd(u.cost.usd) : "–"}${rate != null ? ` (+${fmtUsd(rate)}/h)` : ""} · ${fmtTokens(totalTokens(u))} tokens · ${cache == null ? "–" : `${Math.round(cache)}%`} cache hits`);
    const tools = toolRows(u).slice(0, 5);
    if (tools.length) {
      out.push(`${fit("Tools", 10)}${toolHeader()}`);
      for (const t of tools) out.push(`  ${fit(t.name, 8)}${[t.p50, t.p95].map((v) => fit(fmtDur(v), 6, { right: true })).join("")}${fit(String(t.count), 7, { right: true })}${fit(String(t.errors), 6, { right: true })}`);
    }
    const { running, done } = agentCounts(u);
    if (running || done) out.push(`Agents   ${running} running · ${done} done`);
  } else if (view === "git") {
    const g = state.git;
    const l = g.local;
    const st = l ? syncPieces(l) : null;
    out.push(`${g.repo?.name || "repository"}${l ? ` · ⎇ ${l.branch} ${st.sync.map((p) => p.text).join("")} · ${st.tree.text}` : ""}`);
    if (g.pr) {
      const c = g.pr.checks;
      out.push(`PR #${g.pr.number} ${prState(g.pr).text}: ${g.pr.title}`);
      out.push(`  checks ✓${c.pass} ●${c.pending} ✗${c.fail} · ${mergePiece(g.pr).text}`);
      const revs = g.pr.reviews.map((r) => `${r.state === "APPROVED" ? "✓" : "✗"} ${r.login}`).concat(g.pr.requested.map((x) => `● ${x}`));
      if (revs.length) out.push(`  reviews ${revs.join("  ")}`);
      out.push(`  ${g.pr.url}`);
    }
    for (const p of g.prs.filter((p) => p.number !== g.pr?.number).slice(0, 5)) out.push(`#${p.number} ${clip(p.title, 50)}  ${prPill(p, g).text}`);
    for (const r of g.runs.slice(0, 3)) out.push(`${runGlyph(r, now).g} ${r.name} · ${r.branch} · ${r.status === "completed" ? age(r.updatedAt, now) : "running"}`);
  } else {
    for (const s of allSessions()) {
      out.push(`${sessionBusy(s) ? "●" : "○"} ${s.project}${s.branch ? ` (${s.branch})` : ""} · ${shortModel(s.model)} · ${s.activity?.state ?? "idle"}${s.cost != null ? ` · ${fmtUsd(s.cost)}` : ""}`);
      for (const a of s.agents ?? []) out.push(`   ${isEnded(a.status) ? (a.status === "completed" ? "✓" : "✗") : "◐"} ${a.type}: ${clip(a.description, 40)}${a.top ? ` (${a.top})` : ""}`);
    }
  }
  return out.join("\n");
}

files.hooks/theme.mjs:
// squad-chat's look: a warm "classic" palette (coral accent, amber, sky, leaf
// green on the terminal's own background), with grey card borders and meta
// text from the person's theme. Fixed hex colors, so the accents read the
// same in every theme.

export const theme = {
  accent: "#D97757",       // coral: title, active tab, you, focused input, "new"
  onAccent: "#1F1E1D",     // text drawn on the accent
  amber: "#E2B86B",        // secondary highlight: unread badges, the band's "new"
  sky: "#7FB6E2",          // informational dots
  you: "#7FB6E2",          // your name: set apart from your coral bubbles
  online: "#6CC070",       // online, live
  // Message bubbles: fixed text and fill, so they read in light and dark themes.
  mineBubble: "#D97757",
  mineText: "#1F1E1D",
  theirBubble: "#3A3836",
  theirText: "#ECE7E1",
  border: "inactive",      // card borders
  muted: "subtle",         // meta text: times, counts, hints
  warn: "#E2B86B",
  error: "#E06C75",
  // The built-in rooms, each with its own color from the same warm palette:
  // its tab, its card titles and its meters' fill.
  usage: "#7FB6E2",        // sky
  git: "#6CC070",          // leaf
  agents: "#C8A2E0",       // lilac
};

// Green, amber or red for how full something is (a percent, 0-100).
export function level(pct) {
  if (pct >= 85) return theme.error;
  if (pct >= 60) return theme.amber;
  return theme.online;
}

// Warm, distinct name colors for friends. Sky blue is kept for "you", and
// coral for your bubbles, so neither appears here.
const NAME_COLORS = ["#E2B86B", "#6CC070", "#C8A2E0", "#E58FA8", "#6FC2B5", "#D9A877", "#B8C46A", "#D4A5A5"];

// The same person always gets the same color, in every pane.
export function nameColor(userId = "") {
  let h = 0;
  for (const ch of String(userId)) h = (h * 31 + ch.codePointAt(0)) >>> 0;
  return NAME_COLORS[h % NAME_COLORS.length];
}

export const glyph = {
  brand: "◆",
  on: "●",
  off: "○",
  busy: "◐",
  quiet: "🔕",
